llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "In seven patients, tetrabenazine—a close structural analogue with a tertiary amine, aromatic methoxy, and cyclohexanone—had a mean absolute oral bioavailability of 0.049 ± 0.032 after oral dosing, far below the 20% threshold; this is the highest-transfer direct human evidence and strongly supports low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Aniracetam, a methoxy-substituted heterocycle, is reported to have extremely low oral bioavailability in humans due to rapid metabolism after absorption, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Meptazinol, a basic phenolic analgesic with a tertiary amine, has absolute oral bioavailability of only 4.5–8.7% in humans, indicating extensive first-pass metabolism and supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine, a phenolic benzomorphan with a basic amine, has a mean absolute oral bioavailability of 18% in healthy subjects, just below the 20% threshold, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "2-Methoxyestradiol, a phenolic methoxy steroid, has clinical oral bioavailability of only 1–2% in patients, showing that favorable physicochemical properties do not overcome first-pass metabolism; this supports low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Estradiol, a low-molecular-weight phenolic steroid, has absolute oral bioavailability of approximately 1–5% in women due to extensive intestinal and hepatic first-pass metabolism, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In one healthy subject, pentazocine tablets gave an absolute oral bioavailability of 31.6%, above the 20% threshold; however, this is a single outlier against a mean of 18% and does not outweigh the consistent low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence, led by the high-transfer tetrabenazine data (F≈5%) and supported by pentazocine, meptazinol, 2-methoxyestradiol, estradiol, aniracetam, and curcumin, indicates extensive first-pass metabolism and oral bioavailability below 20% for this phenolic tertiary-amine alkaloid. The favorable physicochemical prior is overridden by direct human bioavailability measurements in close analogues. Prediction: low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for narwedine itself; extrapolation relies on analogue transfer.",
    "The specific metabolic enzymes and first-pass extraction of the query are not directly characterized.",
    "The query's phenol and ketone may alter conjugation or clearance relative to tetrabenazine, but the direction of any effect is not established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

